message.content:
{
  "title": "Rescue Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by broken statues under a gray sky, with rusted portcullis half-raised.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople whisper warnings in the market square.",
      "visual_description": "Frightened villagers huddle near a dry fountain, pointing toward a distant tower, with old royal banners hanging tattered from windows.",
      "characters": ["Kael the Ranger", "Elder Nessa", "Frightened Crowd"]
    },
    {
      "scene_number": 3,
      "caption": "An armored patrol blocks the main avenue.",
      "visual_description": "Three armored soldiers with glowing swords stand before a barricade of rubble, their helmets hiding all expression.",
      "characters": ["Torvin the Warrior", "Armored Patrol"]
    },
    {
      "scene_number": 4,
      "caption": "The mage opens a hidden door in a wall.",
      "visual_description": "Mira traces runes on a mossy stone wall; the stones shimmer and slide apart revealing a dark passage.",
      "characters": ["Mira the Mage", "Kael the Ranger"]
    },
    {
      "scene_number": 5,
      "caption": "Inside a cursed tower, illusions torment the party.",
      "visual_description": "Ghostly figures of lost loved ones reach out from swirling mist, as the party backs against a spiral staircase.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior", "Illusion Specters"]
    },
    {
      "scene_number": 6,
      "caption": "They find the prisoner chained in the tower's heart.",
      "visual_description": "A young woman with a glowing amulet is chained to a stone pillar, surrounded by flickering torches.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior", "Lyra the Prisoner"]
    },
    {
      "scene_number": 7,
      "caption": "A magical trap triggers as they free Lyra.",
      "visual_description": "Runes on the floor blaze red and chains fly from the walls toward the group.",
      "characters": ["Mira the Mage", "Lyra the Prisoner", "Torvin the Warrior"]
    },
    {
      "scene_number": 8,
      "caption": "On the tower roof, a dragon circles overhead.",
      "visual_description": "A massive black dragon with ember eyes glides low over the tower, its shadow swallowing the parapet.",
      "characters": ["Kael the Ranger", "Lyra the Prisoner", "The Black Dragon"]
    },
    {
      "scene_number": 9,
      "caption": "They descend through a crumbling library.",
      "visual_description": "Rotting bookshelves lean at dangerous angles, and a chandelier of bones sways in the draft.",
      "characters": ["Mira the Mage", "Lyra the Prisoner", "Kael the Ranger"]
    },
    {
      "scene_number": 10,
      "caption": "A patrol corners them in a narrow alley.",
      "visual_description": "Armored soldiers block both ends of a cramped alley lined with broken carts.",
      "characters": ["Torvin the Warrior", "Armored Patrol", "Kael the Ranger"]
    },
    {
      "scene_number": 11,
      "caption": "Lyra uses her amulet to open a magic door.",
      "visual_description": "Lyra presses her glowing amulet against a stone door etched with celestial symbols; the door dissolves into light.",
      "characters": ["Lyra the Prisoner", "Mira the Mage"]
    },
    {
      "scene_number": 12,
      "caption": "They cross the royal throne room under fallen banners.",
      "visual_description": "A vast hall with a cracked throne, faded royal banners trailing in dust motes, and shattered stained glass.",
      "characters": ["Kael the Ranger", "Torvin the Warrior", "Lyra the Prisoner", "Mira the Mage"]
    },
    {
      "scene_number": 13,
      "caption": "The dragon lands on the palace roof above them.",
      "visual_description": "Through a hole in the ceiling, the dragon's head peers down, its breath misting in the cold air.",
      "characters": ["The Black Dragon", "Kael the Ranger", "Lyra the Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "Mira creates a diversion with a spell.",
      "visual_description": "Mira hurls a bolt of blue lightning that shatters a column, sending rubble toward the dragon's face.",
      "characters": ["Mira the Mage", "The Black Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "The party flees through the royal gardens.",
      "visual_description": "Overgrown hedges and dead fountains stretch toward a distant wall, with thorny vines snatching at their clothes.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior", "Lyra the Prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "Guards rush to the bridge gatehouse.",
      "visual_description": "Soldiers sprint to raise a portcullis at the bridge entrance, torches bobbing in the dusk.",
      "characters": ["Armored Patrol", "Torvin the Warrior"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the stone bridge.",
      "visual_description": "The party races across a narrow stone bridge over a chasm, with the dragon diving toward them from above.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior", "Lyra the Prisoner", "The Black Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "The stone bridge crumbles into the gorge as the party reaches the far side, the dragon roaring in frustration.",
      "characters": ["Kael the Ranger", "Mira the Mage", "Torvin the Warrior", "Lyra the Prisoner", "The Black Dragon"]
    }
  ]
}

